(function(){'use strict';if(window.__SP_L8T2_NAV_FIX_20260902)return;window.__SP_L8T2_NAV_FIX_20260902=true;const KEY='SP_L8_LAST_TASK_T2';if(document.body.dataset.page==='task'){const id=new URLSearchParams(location.search).get('task');if(id)try{sessionStorage.setItem(KEY,id);localStorage.setItem(KEY,id)}catch(e){}return}if(document.body.dataset.page!=='theme')return;let done=false;function run(){if(done)return true;let id='';try{id=sessionStorage.getItem(KEY)||localStorage.getItem(KEY)||''}catch(e){}if(!id)return false;const link=[...document.querySelectorAll('a.l8-task-card')].find(a=>{try{return new URL(a.href,location.href).searchParams.get('task')===id}catch(e){return false}});if(!link)return false;done=true;link.style.scrollMarginTop='18px';requestAnimationFrame(()=>requestAnimationFrame(()=>link.scrollIntoView({behavior:'auto',block:'center'})));return true}const root=document.getElementById('app');if(root)new MutationObserver(run).observe(root,{childList:true,subtree:true});[100,250,500,900,1600,2600].forEach(ms=>setTimeout(run,ms));})();